using System.Diagnostics;
using CubeScope.Core.Models;
using CubeScope.Core.Project;
using CubeScope.Core.State;
using Microsoft.AnalysisServices;

namespace CubeScope.Core.Ssas;

/// <summary>
/// Processing of a cube, measure group, partition or dimension from the State panel.
///
/// The XMLA is generated by AMO itself (<c>Server.CaptureXml</c>: the <c>Process</c> call is
/// recorded, not sent — checked on the dev server, the object kept its date) and shown to the
/// user. A run captures it again from the same object and mode — never from text sent by the
/// client — and executes it (<c>Server.Execute</c>); the capture is deterministic, so what was
/// previewed is what runs unless the object changed in between.
/// Short AMO connection of its own, like <see cref="CacheService"/>: it never waits for the
/// lock of the ADOMD session. No progress streaming: a long process is cancelled from the
/// Sessions panel. One run at a time: a second request is refused while one is in flight.
///
/// Every run goes through <see cref="ProductionActionGuard"/> BEFORE the connection to the
/// target server, and is logged in SQLite, refused or not.
///
/// OBSERVED (17.0.25.218 dev): <c>Execute</c> does not throw for a server-side error — an
/// unknown ID or malformed XMLA comes back as an <c>XmlaError</c> in the results; a success
/// is one result without messages.
/// </summary>
public sealed class ProcessService(SsasSession session, StateStore store)
{
    private readonly SemaphoreSlim _running = new(1, 1);

    public Task<ProcessPreview> PreviewAsync(ProcessRequest request, CancellationToken ct = default)
    {
        var (server, catalog) = Context();
        bool production = !DevServerGuard.IsDev(store.GetDevServers(), server);
        if (ProductionActionGuard.HardRefusal(production, request.Target.Kind, request.Mode) is { } refusal)
            return Task.FromResult(new ProcessPreview(FallbackLabel(request.Target), "", production, [], refusal));

        return Task.Run(() => WithDatabase(server, catalog, (amo, db) =>
        {
            var (obj, label) = Resolve(db, request.Target);
            // Update keeps the partitions processed but drops their flexible aggregations and
            // indexes (documented): listed too, the UI warns without refusing.
            var affected = ProductionActionGuard.UnprocessesDependents(request.Target.Kind, request.Mode)
                           || (request.Target.Kind == ProcessObjectKind.Dimension && request.Mode == ProcessMode.Update)
                ? AffectedMeasureGroups(db, request.Target.DimensionId!)
                : [];
            return new ProcessPreview(label, Capture(amo, obj, request.Mode), production, affected, null);
        }), ct);
    }

    public Task<ProcessResult> RunAsync(ProcessRequest request, CancellationToken ct = default)
    {
        var (server, catalog) = Context();
        return RunAsync(server, catalog, request, store.GetDevServers(), ct);
    }

    /// <remarks>Server and dev list passed in: lets a test prove the refusal comes before any connection.</remarks>
    internal async Task<ProcessResult> RunAsync(string server, string catalog, ProcessRequest request,
        IReadOnlyList<string> devServers, CancellationToken ct = default)
    {
        bool production = !DevServerGuard.IsDev(devServers, server);
        // IDs until the object is resolved: a refused attempt must still say what was targeted.
        string label = FallbackLabel(request.Target);
        var sw = new Stopwatch();
        ProcessResult result;
        bool acquired = false;
        try
        {
            // BEFORE any connection to the target server.
            ProductionActionGuard.EnsureAllowed(server, devServers, request.ConfirmServer,
                request.Target.Kind, request.Mode);
            if (!(acquired = _running.Wait(0)))
                throw new InvalidOperationException("Un traitement est déjà en cours : attendez sa fin.");

            result = await Task.Run(() => WithDatabase(server, catalog, (amo, db) =>
            {
                var (obj, objectLabel) = Resolve(db, request.Target);
                label = objectLabel;
                string xmla = Capture(amo, obj, request.Mode);
                sw.Start();
                var results = amo.Execute(xmla);
                sw.Stop();
                var messages = Messages(results);
                // At least one result and no error: an empty answer is not a success.
                bool success = results.Count > 0 && messages.All(m => m.Severity != "Error");
                return new ProcessResult(success, sw.ElapsedMilliseconds, messages);
            }), ct);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            // Refusals and failures are logged too: the log answers "what was attempted on prod".
            // A connection lost during Execute: the server may still be processing — the elapsed
            // time says how long we waited.
            Log(server, catalog, label, request.Mode, production, sw.ElapsedMilliseconds, false, ex.GetBaseException().Message);
            throw;
        }
        finally
        {
            if (acquired) _running.Release();
        }

        Log(server, catalog, label, request.Mode, production, result.DurationMs, result.Success,
            result.Success ? null : result.Messages.FirstOrDefault(m => m.Severity == "Error")?.Text);
        return result;
    }

    /// <summary>A log that cannot be written must not turn a committed process into a reported failure.</summary>
    private void Log(string server, string catalog, string label, ProcessMode mode, bool production,
        long durationMs, bool success, string? error)
    {
        try { store.AddProcessLog(server, catalog, label, mode.ToString(), production, durationMs, success, error); }
        catch (Exception ex) { Console.WriteLine($"[CubeScope] Processing log not written: {ex.GetBaseException().Message}"); }
    }

    internal static string FallbackLabel(ProcessTarget t) => t.Kind switch
    {
        ProcessObjectKind.Dimension => $"Dimension {t.DimensionId}",
        ProcessObjectKind.Cube => $"Cube {t.CubeId}",
        ProcessObjectKind.MeasureGroup => $"{t.CubeId} › {t.MeasureGroupId}",
        _ => $"{t.CubeId} › {t.MeasureGroupId} › {t.PartitionId}",
    };

    private (string Server, string Catalog) Context()
        => (session.Server ?? throw new InvalidOperationException("Aucune connexion ouverte."),
            session.Catalog ?? throw new InvalidOperationException("Aucun catalogue sélectionné."));

    private static T WithDatabase<T>(string server, string catalog, Func<Server, Database, T> work)
    {
        using var amo = new Server();
        amo.Connect($"Data Source={server};Integrated Security=SSPI;");
        try
        {
            var db = amo.Databases.FindByName(catalog)
                ?? throw new InvalidOperationException($"Base « {catalog} » introuvable ou illisible sur {server}.");
            return work(amo, db);
        }
        finally
        {
            // A failing disconnect must not mask the outcome of the work above.
            try
            {
                amo.CaptureXml = false;
                amo.Disconnect();
            }
            catch (Exception ex) { Console.WriteLine($"[CubeScope] AMO disconnect failed: {ex.GetBaseException().Message}"); }
        }
    }

    /// <summary>The object and a readable label ("Cube › Measure group › Partition").</summary>
    internal static (ProcessableMajorObject Object, string Label) Resolve(Database db, ProcessTarget t)
    {
        if (t.Kind == ProcessObjectKind.Dimension)
        {
            var dim = db.Dimensions.Find(t.DimensionId ?? "")
                ?? throw new InvalidOperationException($"Dimension introuvable : {t.DimensionId}");
            return (dim, dim.Name);
        }
        var cube = db.Cubes.Find(t.CubeId ?? "") ?? throw new InvalidOperationException($"Cube introuvable : {t.CubeId}");
        if (t.Kind == ProcessObjectKind.Cube) return (cube, cube.Name);
        var mg = cube.MeasureGroups.Find(t.MeasureGroupId ?? "")
            ?? throw new InvalidOperationException($"Groupe de mesures introuvable : {t.MeasureGroupId}");
        if (t.Kind == ProcessObjectKind.MeasureGroup) return (mg, $"{cube.Name} › {mg.Name}");
        var p = mg.Partitions.Find(t.PartitionId ?? "")
            ?? throw new InvalidOperationException($"Partition introuvable : {t.PartitionId}");
        return (p, $"{cube.Name} › {mg.Name} › {p.Name}");
    }

    /// <summary>AMO records the Process call instead of sending it, then hands back the XMLA batch.</summary>
    private static string Capture(Server amo, ProcessableMajorObject obj, ProcessMode mode)
    {
        amo.CaptureLog.Clear();
        amo.CaptureXml = true;
        try { obj.Process(ToProcessType(mode)); }
        finally { amo.CaptureXml = false; }
        string xmla = amo.ConcatenateCaptureLog(true, false);
        amo.CaptureLog.Clear();
        // Never send an empty batch: it would "succeed" without processing anything.
        if (!xmla.Contains("<Process", StringComparison.Ordinal))
            throw new InvalidOperationException("AMO n'a produit aucune commande de traitement pour cet objet.");
        return xmla;
    }

    internal static ProcessType ToProcessType(ProcessMode mode) => mode switch
    {
        ProcessMode.Default => ProcessType.ProcessDefault,
        ProcessMode.Full => ProcessType.ProcessFull,
        ProcessMode.Data => ProcessType.ProcessData,
        ProcessMode.Update => ProcessType.ProcessUpdate,
        _ => throw new ArgumentOutOfRangeException(nameof(mode)),
    };

    /// <summary>"Cube › Measure group" of every measure group that uses the database dimension.</summary>
    internal static IReadOnlyList<string> AffectedMeasureGroups(Database db, string dimensionId)
    {
        var list = new List<string>();
        foreach (Cube cube in db.Cubes)
        {
            var cubeDims = cube.Dimensions.Cast<CubeDimension>()
                .Where(cd => cd.DimensionID == dimensionId).Select(cd => cd.ID).ToHashSet();
            if (cubeDims.Count == 0) continue;
            foreach (MeasureGroup mg in cube.MeasureGroups)
                if (mg.Dimensions.Cast<MeasureGroupDimension>().Any(d => cubeDims.Contains(d.CubeDimensionID)))
                    list.Add($"{cube.Name} › {mg.Name}");
        }
        return list;
    }

    private static List<ProcessMessage> Messages(XmlaResultCollection results)
    {
        var list = new List<ProcessMessage>();
        foreach (XmlaResult r in results)
            foreach (XmlaMessage m in r.Messages)
                list.Add(new ProcessMessage(m is XmlaError ? "Error" : m is XmlaWarning ? "Warning" : "Info", m.Description));
        return list;
    }
}
